#!/usr/bin/env bash
set -euo pipefail
source "$(dirname "$0")/lib/common.sh";target="${1:-}";topic=product-search-revisions
offsets(){ local when="$1";"${compose[@]}" exec -T kafka /opt/kafka/bin/kafka-get-offsets.sh --bootstrap-server kafka:9092 --topic "$topic" --time "$when" 2>/dev/null|awk -F: 'BEGIN{printf "["}{printf "%s{\"partition\":%s,\"offset\":%s}",s,$2,$3;s=","}END{print "]"}';}
beginning="$(offsets -2)";end="$(offsets -1)";committed="$("${compose[@]}" exec -T kafka /opt/kafka/bin/kafka-consumer-groups.sh --bootstrap-server kafka:9092 --group product-search-sync-v1 --describe 2>/dev/null|awk 'BEGIN{printf "["}$2=="product-search-revisions"{offset=$4~/^[0-9]+$/?$4:"null";lag=$6~/^[0-9]+$/?$6:"null";printf "%s{\"partition\":%s,\"offset\":%s,\"lag\":%s}",s,$3,offset,lag;s=","}END{print "]"}')";shadow="$(MYSQL_PWD="${MYSQL_PWD:?MYSQL_PWD required}" mysql --protocol=TCP -h"${MYSQL_HOST:-127.0.0.1}" -P"${MYSQL_PORT:-3308}" -u"${MYSQL_USER:-root}" -N -B product_catalog -e "SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('run_id',BIN_TO_UUID(run_id),'phase',phase,'partition_id',partition_id,'next_offset',next_offset)),JSON_ARRAY()) FROM rebuild_partition_offset"|tail -1)";output="$(jq -n --arg topic "$topic" --argjson beginning "$beginning" --argjson end "$end" --argjson committed "$committed" --argjson shadow "$shadow" '{schema_version:1,consistency:"ADMIN_OFFSETS_AT_CAPTURE_TIME",topic:$topic,beginning:$beginning,end:$end,primary:$committed,shadow_and_barrier:$shadow}')";output="$(jq -c -f "$(dirname "$0")/lib/sort-capture.jq" <<<"$output")";if test -n "$target";then printf '%s\n' "$output"|atomic_json "$target";else jq -S .<<<"$output";fi
